"use client";
/**
 * Gestion Cabinet (source L26099–L26666, v66): operational domain over the Calendar's appointments (visit stages with
 * an explicit transition table applied through the Calendar's API under the caller's mapped role, check-in and
 * walk-ins, practitioner operational status, room readiness and issues reported to the Calendar through the bus,
 * operational tasks, administrative follow-up read from Patients, reports with defined metrics), synthetic seed, the
 * shell (HR & Payroll component classes), dashboard, reception, visit drawer, waiting room with the privacy-safe public
 * display, daily operations timeline, practitioners, services catalogue, rooms & equipment, administrative follow-up,
 * tasks, reports, configuration, audit, and the integrations with Calendar (readiness tags, drawer link) and Patients.
 *
 * Deliberate structure (ADR-04 exception, as for HR, Billing, Patients and Calendar): typed imperative island filling
 * the `.hr.cbapp` container. The code below is the source's own text with types added; the OS integration
 * (L26667–L26684) is replaced by src/apps/cabinet/CabinetApp.tsx. Module-level integrations (Calendar and Patients
 * hooks, the Calendar-window click listener, bus consumers) are installed by cbInstallIntegrations(), called only when
 * the healthcare suite runs natively.
 *
 * Simulated as in the source (S class): roles are a browser-side demo; visits, tasks and issues are synthetic; the
 * public waiting-room display is previewed inside the app.
 */
import { L4 as L4core } from "@/lib/i18n/core";
import { isLang, type Lang } from "@/lib/i18n/langs";
import { useShell } from "@/os/state/shell";
import { osMenu as osMenuCore, type MenuItem } from "@/os/menu/OsMenu";
import { dcSaveFile } from "@/lib/download";
import { openApp } from "@/os/windows/apps";
import { useWm } from "@/os/windows/wm";
import { pushNc } from "@/os/notifications/nc";
import { hrE, hri, hrRM, hrNf, hrCount, hrSt, HR, HRI } from "@/apps/hr/hr";
import { biSt } from "@/apps/billing/billing";
import { PA, PA_HOOKS, paSt, paFind, paName, paConsent, paDate, paOpenPatient, paCompleteness, paErr, PaErr, type PaPat } from "@/apps/patients/patients";
import { CL, CL_KEY, CL_HOOKS, CL_ACTIVE, CL_CANCEL, CL_ORG_TZ, CL_RTYPES, clSt, clReload, clGet, clGo, clDrawer, clWizard, clRoot, clAddD, clAltsHTML, clBook, clCan, clD, clDateOf, clErr, clIso, clItems, clLoc, clPrBlocks, clPrColor, clPrWindows, clRes, clResBlocks, clSetStatus, clStBadge, clSvc, clSvcName, clT, clTimeOf, clToday, clTz, clWd, clZms, ClErr, type ClAppt, type ClRes } from "@/apps/calendar/calendar";
import { RM, RM_SH_KEY, RM_SPECS, rmEmit, rmOn, rmCatchUp, rmBusSt, rmShSt, rmShSave, rmPrac, rmPracName, rmPracJob, rmPracs, rmSpecName, rmPracEmployment, rmEsts, rmEstName, rmNotify, rmSafeName, type RmEv, type RmSvc, type RmPrac } from "@/apps/health/rm";

/* ---------- typed model ---------- */
type Bag = Record<string, unknown>;
type Dict = Record<string, string>;
export type CbEvent = { at: string; stage: string; by: string; note?: string; src?: string };
/** Operational state of one calendar appointment (no copy of the appointment: its id and stage timestamps). */
export type CbVisit = { appt: string; tenant: string; stage: string; events: CbEvent[]; room: string | null; notes: string; alerts: unknown[]; synthetic?: boolean; arrivedAt?: string; waitingAt?: string; calledAt?: string; startedAt?: string; doneAt?: string; ticket?: number; idOk?: { at: string; by: string }; late?: number; walkin?: boolean };
export type CbReady = { st: string; at?: string; by?: string; note?: string; issue?: string | null };
export type CbIssue = { id: string; tenant: string; rid: string; kind: string; title: string; desc: string; sev: string; status: string; at: string; by: string; unavail: { from: string; to: string; start?: string; end?: string } | null; hist: { at: string; by: string; to: string; note?: string }[]; busKey?: string; task?: string };
export type CbCheck = { t: string; done: boolean; appt?: string | null };
export type CbTask = { id: string; tenant: string; title: string; desc: string; prio: string; due: string; team: string; assignee: string; status: string; refs: Dict; checklist: CbCheck[]; comments: { at: string; by: string; text: string }[]; created: string; by: string; hist: { at: string; by: string; act: string }[]; doneAt?: string };
export type CbAnn = { id: string; at: string; by: string; text: string; est: string; pub?: boolean };
export type CbAudit = { id: string; ts: string; tenant: string; role: string; user: string; act: string; ref: string; detail: string };
export type CbState = {
  v: number; synthetic: boolean; tenant: string; role: string; me: string; rev: number; visits: Record<string, CbVisit>; prSt: Record<string, { st: string; at: string; note: string; date: string; by: string }>; ready: Record<string, CbReady>;
  issues: CbIssue[]; tasks: CbTask[]; ann: CbAnn[]; audit: CbAudit[]; sent: string[]; hours: Record<string, string[]>; pol: { lateMins: number; walkin: boolean; noShowGrace: number; [k: string]: unknown }; display: { mode: string; showPr: boolean; showRoom: boolean; [k: string]: unknown }; tick?: { d: string; n: number }; [k: string]: unknown;
};
type CbStepO = { ver?: number | null; at?: string; idOk?: boolean; recNote?: string; notify?: boolean; room?: string | null; reason?: string; note?: string };
type CbLane = { id: string; n: string; c: string; its: ClAppt[]; off: [number, number, string, string][]; win: [number, number, string][] | null; rd?: string };
type CbTf = { q?: string; rtab?: string; wmine?: boolean; odate?: string; oby?: string; iss?: string; adOnly?: boolean; adAll?: boolean; tq?: string; rdays?: number; rpr?: string; atab?: string; aq?: string; svcAll?: boolean; team?: string; pr?: string; od?: boolean; [k: string]: string | number | boolean | undefined };
type CbUi = { view: string; arg: string | null; stack: [string, string | null][]; date: string | null; est: string; pr: string; open: Record<string, boolean>; drawer: string | null; tf: CbTf; navOpen?: boolean; opsScrolled?: string; [k: string]: unknown };
type CbApp = { st: CbState | null; ui: CbUi; loadErr?: boolean; saveErr?: boolean; stale?: boolean; syncAt?: number };
type DlgOpts = { wide?: boolean; xl?: boolean; icon?: string; foot?: string; cancel?: boolean; cancelLabel?: string; ok?: boolean; okLabel?: string; danger?: boolean; onOk?: (m: HTMLElementX) => boolean | void; mount?: (m: HTMLElementX) => void };
type CbPageDef = { id: string; g: string; n: string; ic: string; page: (a: string | null) => string; mount?: (R: HTMLElement) => void; hidden?: boolean; perm?: string | string[]; badge?: () => number };
type HTMLElementX = HTMLElement & { _close?: () => void; _t?: ReturnType<typeof setTimeout> };

const lang = (): Lang => { const h = document.documentElement.lang; return isLang(h) ? h : "en"; };
/** L4 (L21374): "fr|en|de|ar" → the current language. */
const L4 = (s: unknown) => L4core(lang(), s as string);
const toast = (m: string) => useShell.getState().showToast(m);
const osMenu = (x: number, y: number, items: (MenuItem | string | null)[]) => osMenuCore(x, y, items as MenuItem[]);
const OS_USER = null as { name?: string } | null;
/** OSW.cabinet / OSW.calendar: open windows, found through the window manager. */
const OSW = { get cabinet() { return cbWinEl() ? { el: cbWinEl()! } : null; }, get calendar() { return useWm.getState().wins.calendar ? {} : null; } };
/** OSW.cabinet.el (the window) — found by its key. */
const cbWinEl = () => document.querySelector<HTMLElement>('.os-win[data-osw="cabinet"]');
/** cbOpen (L26671) and clOpen (L26084): the windows are opened by the shell. */
const cbOpen = (from?: Element | null) => openApp("cabinet", from);
const clOpen = (from?: Element | null) => openApp("calendar", from);
const tgt = (e: Event) => e.target as HTMLInputElement;
/** Module-level document listeners, installed when the window first mounts (after the OS menu's, as in the source). */
const pendingGlobal: (() => void)[] = [];
const onDoc = <K extends keyof DocumentEventMap>(ev: K, fn: (e: DocumentEventMap[K]) => void, cap?: boolean) => { pendingGlobal.push(() => document.addEventListener(ev, fn, cap)); };
let globalDone = false;
export function cbInstallGlobal() { if (globalDone) return; globalDone = true; pendingGlobal.forEach((f) => f()); }

/* ======================================================================================================== */
/* ===== v66 · Gestion Cabinet — operational domain (visits read-model over Calendar appointments, readiness, issues, tasks, reports) =====
   Calendar owns appointments and bookings; Patients owns identity; Cabinet owns visit stages, waiting room, readiness, maintenance coordination, tasks.
   Every appointment status change goes through the Calendar domain API with the caller's mapped role. */
const CB_KEY="remotion-cabinet";
const CB: CbApp={st:null,ui:{view:"dash",arg:null,stack:[],date:null,est:"",pr:"",open:{},drawer:null,tf:{}}};
class CbErr extends Error{k: string;x: unknown;constructor(k: string,x?: unknown){super(k);this.k=k;this.x=x}}
const cbId=(p: string)=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const cbNow=()=>CL.now||Date.now();
const cbToday=()=>clDateOf(cbNow(),CL_ORG_TZ);
const CB_STAGE: Dict={expected:"Attendu|Expected|Erwartet|متوقع",arrived:"Arrivé|Checked in|Eingetroffen|وصل",waiting:"En salle d’attente|Waiting|Wartet|في الانتظار",called:"Appelé|Called|Aufgerufen|تم النداء",inconsult:"En consultation|In consultation|In Behandlung|في الاستشارة",done:"Terminé|Completed|Abgeschlossen|منتهٍ",cancelled:"Annulé|Cancelled|Storniert|ملغى",noshow:"Absent|No-show|Nicht erschienen|غائب"};
const CB_RANK: Record<string, number>={expected:0,arrived:1,waiting:2,called:3,inconsult:4,done:5,cancelled:5,noshow:5};
/* operational transitions (explicit); the calendar transition applied for each is listed */
const CB_TRANS: Record<string, Dict>={expected:{arrived:"checkin",cancelled:"cancel",noshow:"checkin"},arrived:{waiting:"checkin",cancelled:"cancel"},waiting:{called:"visit",inconsult:"consult",cancelled:"cancel"},called:{inconsult:"consult",waiting:"visit"},inconsult:{done:"consult"},done:{},cancelled:{},noshow:{}};
const CB_CALMAP: Dict={arrived:"checkedin",inconsult:"inprogress",done:"completed",cancelled:"cancelled",noshow:"noshow"};
const CB_PRST: Dict={available:"Disponible|Available|Verfügbar|متاح",busy:"Occupé·e|Busy|Beschäftigt|مشغول",break:"En pause|On break|Pause|استراحة",late:"En retard|Running late|Verspätet|متأخر",absent:"Absent·e|Absent|Abwesend|غائب"};
const CB_READY: Dict={ready:"Prête|Ready|Bereit|جاهزة",cleaning:"Nettoyage en cours|Cleaning|Reinigung|تنظيف",prep:"Préparation|Preparing|Vorbereitung|تحضير",out:"Hors service|Out of service|Außer Betrieb|خارج الخدمة"};
const CB_PRIO: Dict={low:"Basse|Low|Niedrig|منخفضة",normal:"Normale|Normal|Normal|عادية",high:"Haute|High|Hoch|مرتفعة",urgent:"Urgente|Urgent|Dringend|عاجلة"};
const CB_TST: Dict={todo:"À faire|To do|Offen|للقيام",doing:"En cours|In progress|In Arbeit|جارٍ",done:"Terminée|Done|Erledigt|منجزة",cancelled:"Annulée|Cancelled|Abgebrochen|ملغاة"};
const CB_TEAMS: Dict={reception:"Accueil|Reception|Empfang|الاستقبال",care:"Équipe de soins|Care team|Behandlungsteam|فريق الرعاية",manager:"Responsable de cabinet|Practice manager|Praxismanagement|مدير العيادة",tech:"Maintenance / logistique|Maintenance / logistics|Haustechnik|الصيانة"};
const CB_ROLES: Record<string, { n: string; p: string[]; cal: string; pa: string; own?: boolean }>={
 reception:{n:"Accueil / secrétariat|Reception|Empfang|الاستقبال",p:["dash.view","patient.search","patient.admin","checkin","visit.status","task.manage","room.ready","report.view"],cal:"reception",pa:"reception"},
 practitioner:{n:"Praticien·ne|Practitioner|Behandler(in)|ممارس",p:["dash.view","patient.search","visit.status","visit.consult","task.manage","room.ready"],cal:"clin",pa:"clin",own:true},
 manager:{n:"Responsable de cabinet|Practice manager|Praxismanager(in)|مدير العيادة",p:["dash.view","patient.search","patient.admin","checkin","visit.status","visit.consult","task.manage","room.ready","room.manage","prac.manage","svc.manage","report.view","export","config","audit.view"],cal:"manager",pa:"reception"},
 admin:{n:"Administrateur·rice plateforme|Platform administrator|Plattform-Admin|مسؤول المنصة",p:["dash.view","config","audit.view","svc.manage","prac.manage","room.manage"],cal:"admin",pa:"admin"}};
const cbRole=()=>CB.st?.role||"reception";
const cbCan=(p: string)=>(CB_ROLES[cbRole()]?.p||[]).includes(p);
const cbMe=()=>CB.st?.me||"pr1";
function cbNeed(p: string){if(!cbCan(p))throw new CbErr("cb_eDenied")}
const cbUser=()=>cbRole()==="practitioner"?rmPracName(cbMe()):((typeof OS_USER!=="undefined"&&OS_USER?.name)||"Nassim");
const cbTenant=()=>CB.st?.tenant||"t1";
/* call another application's domain API with the caller identity mapped to that application's role (server-side authorisation emulation) */
function cbAsCal<T>(fn: () => T){clSt();const S=CL.st;const r=S!.role,m=S!.me;S!.role=CB_ROLES[cbRole()].cal;S!.me=cbMe();try{return fn()}finally{S!.role=r;S!.me=m}}
function cbAsPa<T>(fn: () => T){if(typeof paSt!=="function")return fn();paSt();const S=PA.st;const r=S!.role,m=S!.me;S!.role=CB_ROLES[cbRole()].pa;S!.me=cbMe();try{return fn()}finally{S!.role=r;S!.me=m}}

/* ---------- store ---------- */
function cbSt(): CbState{if(CB.st)return CB.st;let s: CbState | null=null;try{s=JSON.parse(localStorage.getItem(CB_KEY)||"null")}catch(e){CB.loadErr=true}if(!s||s.v!==1||typeof s.visits!=="object")s=cbSeed();CB.st=s;return s}
function cbSave(){const S=CB.st;S!.rev=(S!.rev||0)+1;try{localStorage.setItem(CB_KEY,JSON.stringify(S))}catch(e){CB.saveErr=true;console.warn("cb save",e)}}
function cbReload(){try{const s=JSON.parse(localStorage.getItem(CB_KEY)||"null");if(s&&s.v===1&&CB.st&&(s.rev||0)>(CB.st.rev||0)){const keep={role:CB.st.role,me:CB.st.me};Object.keys(CB.st).forEach(k=>delete CB.st![k]);Object.assign(CB.st,s,keep)}}catch(e){}return CB.st}
function cbLog(act: string,ref?: string | null,detail?: unknown){const S=cbSt();S.audit.unshift({id:cbId("a"),ts:new Date().toISOString(),tenant:cbTenant(),role:cbRole(),user:cbUser(),act,ref:ref||"",detail:String(detail||"").slice(0,160)});if(S.audit.length>800)S.audit.length=800}

/* ---------- visits: operational state per calendar appointment (no appointment copy: only the reference and stage timestamps) ---------- */
function cbAppts(date?: string | null,o: { days?: number; pr?: string }={}){clSt();const tz=CL_ORG_TZ;const d=date||cbToday();const from=clZms(d,"00:00",tz),to=clZms(clAddD(d,o.days||1),"00:00",tz);return clItems(from,to).filter(a=>(!CB.ui.est||a.est===CB.ui.est)&&(!o.pr||a.pr===o.pr)).sort((a,b)=>a.start<b.start?-1:1)}
function cbVisit(id: string){return cbSt().visits[id]||null}
/* the stage shown combines the calendar status (source of truth for the appointment) with the cabinet's finer operational stage */
function cbStage(a: ClAppt){const v=cbVisit(a.id);const s=a.status;if(s==="cancelled")return "cancelled";if(s==="noshow")return "noshow";if(s==="completed")return "done";if(s==="inprogress")return "inconsult";if(s==="checkedin")return v&&["waiting","called"].includes(v.stage)?v.stage:(v?.stage==="arrived"?"arrived":"waiting");return "expected"}
function cbEnsure(a: ClAppt){const S=cbSt();let v=S.visits[a.id];if(!v){v=S.visits[a.id]={appt:a.id,tenant:cbTenant(),stage:"expected",events:[],room:a.room||null,notes:"",alerts:[]}}return v}
function cbStep(id: string,to: string,o: CbStepO={}){const a=cbAsCal(()=>{clReload();return clGet(id)});const from=cbStage(a);const need=(CB_TRANS[from]||{})[to];if(!need)throw new CbErr("cb_eTrans",L4(CB_STAGE[from])+" → "+L4(CB_STAGE[to]||to));
  if(need==="checkin")cbNeed("checkin");if(need==="cancel")cbNeed("checkin");if(need==="visit")cbNeed("visit.status");if(need==="consult"){cbNeed("visit.consult");if(cbRole()==="practitioner"&&a.pr!==cbMe())throw new CbErr("cb_eNotYours")}
  if(o.ver!=null&&a.ver!=null&&!a.series&&a.ver!==o.ver)throw new CbErr("cb_eStale");
  if(to==="noshow"&&Date.parse(a.start)+cbSt().pol.noShowGrace*60000>cbNow())throw new CbErr("cb_eNoShowEarly",cbSt().pol.noShowGrace+" min");
  const calTo=CB_CALMAP[to];if(calTo&&!(to==="arrived"&&a.status==="checkedin")){cbAsCal(()=>clSetStatus(id,calTo,to==="cancelled"?{reason:o.reason||"patient",note:o.note||""}:{}))}
  const S=cbSt();const v=cbEnsure(a);const now=new Date(cbNow()).toISOString();const ev={at:o.at||now,stage:to,by:cbUser(),note:o.note||""};v.events.push(ev);v.stage=to;
  if(to==="arrived"){v.arrivedAt=o.at||now;if(!v.ticket){const T=cbToday();if(!S.tick||S.tick.d!==T)S.tick={d:T,n:0};v.ticket=++S.tick.n}if(o.idOk)v.idOk={at:now,by:cbUser()};const late=Date.parse(v.arrivedAt)-Date.parse(a.start);v.late=late>S.pol.lateMins*60000?Math.round(late/60000):0;if(o.recNote)v.notes=o.recNote}
  if(to==="waiting"&&!v.arrivedAt){v.arrivedAt=now}if(to==="waiting")v.waitingAt=now;if(to==="called")v.calledAt=now;if(to==="inconsult"){v.startedAt=now;if(o.room)v.room=o.room}if(to==="done")v.doneAt=now;
  if(to==="waiting"&&o.notify!==false)cbNotifyPr(a,"arrival");
  cbLog("visit."+to,id,L4(CB_STAGE[from])+" → "+L4(CB_STAGE[to]));rmEmit("visit."+to,{appt:id,pr:a.pr,stage:to},{src:"cabinet",ref:id,key:"visit-"+id+"-"+to+"-"+v.events.length});cbSave();return v}
/* check-in = arrival recorded + waiting; the calendar appointment is updated, never duplicated */
function cbCheckIn(id: string,o: CbStepO={}){cbNeed("checkin");const a0=cbAsCal(()=>clGet(id));if(cbStage(a0)==="expected")cbStep(id,"arrived",o);return cbStep(id,"waiting",{notify:o.notify})}
function cbNotifyPr(a: ClAppt,kind: string){const p=a.pid&&typeof paFind==="function"?paFind(a.pid):null;const who=p?rmSafeName(p.first,p.last):(a.ext?a.ext.name.split(" ")[0]:"—");const S=cbSt();const key=kind+"|"+a.id;S.sent=S.sent||[];if(S.sent.includes(key))return false;S.sent.push(key);if(S.sent.length>500)S.sent.splice(0,100);
  return rmNotify("rmCab",L4({arrival:"Patient arrivé — |Patient arrived — |Patient eingetroffen — |وصل المريض — ",call:"Rappel — |Reminder — |Erinnerung — |تذكير — ",delay:"Retard signalé — |Delay reported — |Verspätung — |تأخير — "}[kind])+rmPracName(a.pr),who+" · "+clTimeOf(Date.parse(a.start),CL_ORG_TZ)+(a.room?" · "+(clRes(a.room)?.n||""):""),{pri:kind==="delay"?"high":"normal",open:()=>{cbOpen();setTimeout(()=>cbGo("waiting"),300)}})}
function cbSetVisitRoom(id: string,rid: string | null){cbNeed("visit.status");const a=cbAsCal(()=>clGet(id));const v=cbEnsure(a);v.room=rid||null;cbLog("visit.room",id,rid||"—");cbSave();return v}
function cbVisitNote(id: string,text: string){cbNeed("checkin");const a=cbAsCal(()=>clGet(id));const v=cbEnsure(a);v.notes=String(text||"").slice(0,500);cbLog("visit.note",id,"note d’accueil");cbSave();return v}
/* walk-in: creates the appointment in Gestion Calendrier (single source of truth), then checks it in */
function cbWalkIn(d: { pid: string | null; svc: string; pr: string; room?: string | null; est: string; idem?: string }){cbNeed("checkin");if(!cbSt().pol.walkin)throw new CbErr("cb_eWalkPolicy");const svc=clSvc(d.svc);if(!svc)throw new CbErr("cb_eInvalid","service");const now=cbNow();const step=5*60000;const start=Math.ceil(now/step)*step;const r=cbAsCal(()=>clBook({pid:d.pid,svc:d.svc,pr:d.pr,room:d.room||null,est:d.est,start:clIso(start),end:clIso(start+svc.dur*60000),status:"confirmed",notesInt:L4("Sans rendez-vous (accueil)|Walk-in (reception)|Ohne Termin|دون موعد"),idem:d.idem},{}));const a=r.item;cbEnsure(a).walkin=true;cbLog("visit.walkin",a.id,clSvcName(d.svc));cbSave();cbCheckIn(a.id,{});return a}

/* ---------- practitioner operational status (not employment status) ---------- */
function cbPrStatus(pr: string){const S=cbSt();const manual=S.prSt[pr];const today=cbAppts(cbToday(),{pr});const cur=today.find(a=>a.status==="inprogress");if(manual&&["break","absent","late"].includes(manual.st)&&manual.date===cbToday())return {st:manual.st,at:manual.at,note:manual.note,cur};if(cur)return {st:"busy",cur};const blk=clPrBlocks(pr,cbToday()).find(([b0,b1])=>cbNow()>=b0&&cbNow()<b1);if(blk)return {st:"absent",note:blk[2]};const win=clPrWindows(pr,cbToday()).some(([w0,w1])=>cbNow()>=w0&&cbNow()<w1);return {st:win?"available":"absent",note:win?"":L4("Hors plage de disponibilité|Outside working hours|Außerhalb der Arbeitszeit|خارج ساعات العمل")}}
function cbSetPrStatus(pr: string,st: string,note?: string){cbNeed("visit.status");if(cbRole()==="practitioner"&&pr!==cbMe())throw new CbErr("cb_eNotYours");if(!CB_PRST[st])throw new CbErr("cb_eInvalid","status");const S=cbSt();S.prSt[pr]={st,at:new Date().toISOString(),note:note||"",date:cbToday(),by:cbUser()};cbLog("prac.status",pr,st);if(st==="late"){cbAppts(cbToday(),{pr}).filter(a=>a.status==="checkedin").forEach(a=>{}) ;rmNotify("rmCab",L4("Retard praticien|Practitioner running late|Behandler verspätet|تأخر الممارس"),rmPracName(pr)+(note?" · "+note:""),{pri:"high"})}cbSave()}
/* delay of the day = actual start (cabinet record) minus scheduled start, for appointments started today */
function cbDelay(pr: string){const l=cbAppts(cbToday(),{pr}).map(a=>({a,v:cbVisit(a.id)})).filter(x=>x.v?.startedAt);if(!l.length)return 0;const last=l[l.length-1];return Math.max(0,Math.round((Date.parse(last.v.startedAt!)-Date.parse(last.a.start))/60000))}

/* ---------- rooms: readiness (cabinet) vs booking (calendar) ---------- */
function cbRooms(){clSt();return clSt().res.filter(r=>clT(r)&&(!CB.ui.est||r.est===CB.ui.est))}
function cbReady(rid: string){const S=cbSt();return S.ready[rid]||{st:"ready"}}
function cbSetReady(rid: string,st: string,note?: string){cbNeed("room.ready");if(!CB_READY[st])throw new CbErr("cb_eInvalid","readiness");const S=cbSt();const prev=S.ready[rid]?.st||"ready";S.ready[rid]={st,at:new Date().toISOString(),by:cbUser(),note:note||""};cbLog("room.ready",rid,prev+" → "+st);
  if(st==="out"&&prev!=="out"){const iss=cbIssue({rid,kind:"room",title:note||L4("Salle hors service|Room out of service|Raum außer Betrieb|الغرفة خارج الخدمة"),sev:"high",unavail:{from:cbToday(),to:cbToday()}},true);S.ready[rid].issue=iss.id}
  if(prev==="out"&&st!=="out"&&S.ready[rid]&&S.ready[rid].issue==null){const open=S.issues.find(i=>i.rid===rid&&i.status!=="resolved"&&i.unavail);if(open)cbResolveIssue(open.id,L4("Remise en service|Back in service|Wieder in Betrieb|إعادة التشغيل"),true)}
  cbSave();if(typeof clRes==="function"&&cbRoomOccupied(rid)&&st!=="ready")rmNotify("rmCab",L4("Salle non prête mais réservée|Room not ready but booked|Raum nicht bereit|الغرفة غير جاهزة"),(clRes(rid)?.n||rid)+" · "+L4(CB_READY[st]),{pri:"high"});return S.ready[rid]}
function cbRoomOccupied(rid: string){const now=cbNow();return cbAppts(cbToday()).some(a=>(a.room===rid||(a.equip||[]).includes(rid))&&CL_ACTIVE(a.status)&&Date.parse(a.start)<=now+30*60000&&Date.parse(a.end)>now)}
function cbRoomNow(r: ClRes){const now=cbNow();const its=cbAppts(cbToday()).filter(a=>(a.room===r.id||(a.equip||[]).includes(r.id))&&CL_ACTIVE(a.status));const cur=its.find(a=>Date.parse(a.start)<=now&&Date.parse(a.end)>now);const next=its.find(a=>Date.parse(a.start)>now);const blk=clResBlocks(r.id,cbToday()).find(([b0,b1])=>now>=b0&&now<b1);const rd=cbReady(r.id).st;
  return {state:rd==="out"||blk?"unavailable":cur?"occupied":rd!=="ready"?"notready":"available",cur,next,count:its.length,blk}}
/* issues: equipment/room problems; an unavailability is communicated to the calendar through an integration event (bookings are never changed here) */
function cbIssue(d: Partial<CbIssue>,internal?: boolean){if(!internal)cbNeed("room.ready");if(!String(d.title||"").trim())throw new CbErr("cb_eInvalid",L4("intitulé|title|Titel|العنوان"));const S=cbSt();const iss: CbIssue={id:cbId("is"),tenant:cbTenant(),rid:d.rid!,kind:d.kind||"equipment",title:d.title!.trim(),desc:d.desc||"",sev:d.sev||"normal",status:"open",at:new Date().toISOString(),by:cbUser(),unavail:d.unavail||null,hist:[{at:new Date().toISOString(),by:cbUser(),to:"open"}]};S.issues.unshift(iss);cbLog("issue.open",d.rid,iss.title);
  if(iss.unavail){const ev=rmEmit("resource.unavailable",{rid:iss.rid,from:iss.unavail.from,to:iss.unavail.to,start:iss.unavail.start||"",end:iss.unavail.end||"",reason:iss.title},{src:"cabinet",ref:iss.id,key:"unavail-"+iss.id});iss.busKey=ev?ev.key:"unavail-"+iss.id;const imp=cbImpacted(iss.rid,iss.unavail.from,iss.unavail.to);if(imp.length){const t=cbTaskSave({title:L4("Replanifier les rendez-vous de |Reschedule bookings of |Termine verlegen: |إعادة جدولة حجوزات ")+(clRes(iss.rid)?.n||""),prio:"high",team:"reception",due:cbToday(),refs:{room:iss.rid},checklist:imp.map(a=>({t:clTimeOf(Date.parse(a.start),CL_ORG_TZ)+" · "+rmPracName(a.pr),done:false,appt:a.id}))},true);iss.task=t.id}}
  cbSave();return iss}
function cbImpacted(rid: string,from: string,to: string){return clItems(clZms(from,"00:00",CL_ORG_TZ),clZms(clAddD(to,1),"00:00",CL_ORG_TZ),{active:true}).filter(a=>(a.room===rid||(a.equip||[]).includes(rid))&&!["completed","inprogress"].includes(a.status))}
function cbIssueStatus(id: string,st: string,note?: string){cbNeed("room.ready");const S=cbSt();const i=S.issues.find(x=>x.id===id);if(!i)throw new CbErr("cb_eNotFound");if(i.status==="resolved")throw new CbErr("cb_eState");if(st==="resolved")return cbResolveIssue(id,note);i.status=st;i.hist.push({at:new Date().toISOString(),by:cbUser(),to:st,note:note||""});cbLog("issue."+st,i.rid,i.title);cbSave();return i}
function cbResolveIssue(id: string,note?: string,internal?: boolean){if(!internal)cbNeed("room.ready");const S=cbSt();const i=S.issues.find(x=>x.id===id);if(!i||i.status==="resolved")throw new CbErr("cb_eState");i.status="resolved";i.hist.push({at:new Date().toISOString(),by:cbUser(),to:"resolved",note:note||""});if(i.unavail)rmEmit("resource.available",{rid:i.rid,of:i.busKey||("unavail-"+i.id)},{src:"cabinet",ref:i.id,key:"avail-"+i.id});if(S.ready[i.rid]?.st==="out"){S.ready[i.rid]={st:"cleaning",at:new Date().toISOString(),by:cbUser(),note:L4("Remise en service à valider|Back in service, to validate|Wieder in Betrieb|إعادة تشغيل")}}cbLog("issue.resolved",i.rid,i.title);cbSave();return i}

/* ---------- tasks (operational only; clinical tasks belong to the clinical record) ---------- */
function cbTaskSave(d: Omit<Partial<CbTask>, "id"> & { id?: string | null },internal?: boolean){if(!internal)cbNeed("task.manage");if(!String(d.title||"").trim())throw new CbErr("cb_eInvalid",L4("intitulé|title|Titel|العنوان"));const S=cbSt();let t=(d.id&&S.tasks.find(x=>x.id===d.id)) as CbTask | undefined;const now=new Date().toISOString();
  if(!t){t=<CbTask><unknown>{id:cbId("t"),tenant:cbTenant(),status:"todo",created:now,by:cbUser(),comments:[],hist:[{at:now,by:cbUser(),act:"create"}]};S.tasks.unshift(t)}else t.hist.push({at:now,by:cbUser(),act:"edit"});
  Object.assign(t,{title:d.title!.trim(),desc:d.desc||"",prio:CB_PRIO[d.prio!]?d.prio:"normal",due:d.due||"",team:CB_TEAMS[d.team!]?d.team:"reception",assignee:d.assignee||"",refs:Object.assign({},t.refs||{},d.refs||{}),checklist:(d.checklist||t.checklist||[]).map(c=>({t:c.t,done:!!c.done,appt:c.appt||null}))});
  cbLog(d.id?"task.edit":"task.create",t.id,t.title);if(!d.id)rmNotify("rmCab",L4("Nouvelle tâche — |New task — |Neue Aufgabe — |مهمة جديدة — ")+L4(CB_TEAMS[t.team]),t.title,{pri:t.prio==="urgent"||t.prio==="high"?"high":"low",open:()=>{cbOpen();setTimeout(()=>cbGo("tasks"),300)}});cbSave();return t}
function cbTaskStatus(id: string,st: string){cbNeed("task.manage");const S=cbSt();const t=S.tasks.find(x=>x.id===id);if(!t)throw new CbErr("cb_eNotFound");if(!CB_TST[st])throw new CbErr("cb_eInvalid");if(st==="done"&&t.checklist.some(c=>!c.done))throw new CbErr("cb_eChecklist");t.status=st;t.hist.push({at:new Date().toISOString(),by:cbUser(),act:st});if(st==="done")t.doneAt=new Date().toISOString();cbLog("task."+st,id,t.title);if(st==="done")rmEmit("task.completed",{task:id},{src:"cabinet",ref:id,key:"task-done-"+id});cbSave();return t}
function cbTaskCheck(id: string,i: number,on: boolean){cbNeed("task.manage");const t=cbSt().tasks.find(x=>x.id===id);if(!t||!t.checklist[i])throw new CbErr("cb_eNotFound");t.checklist[i].done=!!on;t.hist.push({at:new Date().toISOString(),by:cbUser(),act:(on?"check ":"uncheck ")+(i+1)});if(t.status==="todo"&&on)t.status="doing";cbSave();return t}
function cbTaskComment(id: string,text: string){cbNeed("task.manage");if(!String(text||"").trim())throw new CbErr("cb_eInvalid",L4("commentaire|comment|Kommentar|تعليق"));const t=cbSt().tasks.find(x=>x.id===id);if(!t)throw new CbErr("cb_eNotFound");t.comments.push({at:new Date().toISOString(),by:cbUser(),text:text.trim().slice(0,600)});cbSave();return t}
const cbTicket=(v: CbVisit | null | undefined)=>v&&v.ticket?"A-"+String(v.ticket).padStart(3,"0"):"";
const cbOverdue=(t: CbTask)=>t.status!=="done"&&t.status!=="cancelled"&&t.due&&t.due<cbToday();

/* ---------- administrative follow-up: reads Patients (admin scope only), never clinical content ---------- */
function cbAdminChecks(p: PaPat | null | undefined){if(!p)return [];const out=[];const c=typeof paCompleteness==="function"?paCompleteness(p):{miss:[]};c.miss.filter(m=>m.k!=="allergy").forEach(m=>out.push({k:m.k,l:L4(m.l)}));if(paConsent(p,"care")!=="granted")out.push({k:"ccare",l:L4("Consentement aux soins non documenté|Consent to care not recorded|Einwilligung fehlt|الموافقة غير موثقة")});
  const corr=(paSt().corr||[]).filter(x=>x.pid===p.id&&x.status==="open").length;if(corr)out.push({k:"corr",l:corr+" "+L4("demande(s) de correction ouverte(s)|open correction request(s)|offene Korrekturanträge|طلبات تصحيح مفتوحة")});
  const reps=(p.rel||[]).filter(r=>!r.to&&r.verif==="unverified"&&(r.scope||[]).length);if(reps.length)out.push({k:"rep",l:L4("Représentant à vérifier|Representative to verify|Vertreter prüfen|ممثل للتحقق")});return out.filter((x,i,a)=>a.findIndex(y=>y.k===x.k)===i)}

/* ---------- reports: metrics computed from records (definitions shown in the UI) ---------- */
function cbReport(days: number,o: { est?: string; pr?: string }={}){clSt();const to=cbToday();const from=clAddD(to,-(days-1));const items=clItems(clZms(from,"00:00",CL_ORG_TZ),clZms(clAddD(to,1),"00:00",CL_ORG_TZ)).filter(a=>Date.parse(a.start)<=cbNow()&&(!o.est||a.est===o.est)&&(!o.pr||a.pr===o.pr));
  const vis=items.map(a=>({a,v:cbVisit(a.id)}));const planned=vis.filter(x=>x.a.status!=="cancelled");const arrived=vis.filter(x=>x.v?.arrivedAt||["checkedin","inprogress","completed"].includes(x.a.status));const recorded=vis.filter(x=>x.v?.arrivedAt&&x.v?.startedAt);
  const waits=recorded.map(x=>(Date.parse(x.v.startedAt!)-Date.parse(x.v.arrivedAt!))/60000).filter(w=>w>=0);const buckets=[[0,5],[5,10],[10,20],[20,30],[30,Infinity]].map(([a,b])=>({a,b,n:waits.filter(w=>w>=a&&w<b).length}));
  const delays: Record<string, number[]>={};recorded.forEach(x=>{const d=(Date.parse(x.v.startedAt!)-Date.parse(x.a.start))/60000;(delays[x.a.pr]=delays[x.a.pr]||[]).push(d)});
  const byPr: Record<string, { n: number; min: number; done: number; noshow: number; cancel: number }>={};items.forEach(a=>{const r=byPr[a.pr]=byPr[a.pr]||{n:0,min:0,done:0,noshow:0,cancel:0};r.n++;if(CL_ACTIVE(a.status))r.min+=(Date.parse(a.end)-Date.parse(a.start))/60000;if(a.status==="completed")r.done++;if(a.status==="noshow")r.noshow++;if(a.status==="cancelled")r.cancel++});
  const rooms=clSt().res.filter(r=>clT(r)&&r.kind==="room"&&(!o.est||r.est===o.est)).map(r=>{const hrs=cbSt().hours[r.est]||["08:00","19:00"];let open=0,booked=0,down=0;for(let i=0;i<days;i++){const d=clAddD(from,i);if(clWd(d)===0)continue;const o0=clZms(d,hrs[0],CL_ORG_TZ),o1=clZms(d,hrs[1],CL_ORG_TZ);open+=(o1-o0)/60000;items.filter(a=>a.room===r.id&&CL_ACTIVE(a.status)&&clDateOf(Date.parse(a.start),CL_ORG_TZ)===d).forEach(a=>{booked+=Math.min(o1,Date.parse(a.end))/60000-Math.max(o0,Date.parse(a.start))/60000});clResBlocks(r.id,d).forEach(([b0,b1])=>{down+=Math.max(0,Math.min(o1,b1)-Math.max(o0,b0))/60000})}return {r,open,booked,down,util:open?booked/(open-down||open):0}});
  const S=cbSt();const tasks=S.tasks.filter(t=>t.created.slice(0,10)>=from);const hours: Record<string, number>={};arrived.forEach(x=>{const t=x.v?.arrivedAt;if(!t)return;const h=clTimeOf(Date.parse(t),CL_ORG_TZ).slice(0,2);hours[h]=(hours[h]||0)+1});
  return {from,to,days,n:items.length,planned:planned.length,arrived:arrived.length,checkinRate:planned.length?arrived.length/planned.length:0,completed:items.filter(a=>a.status==="completed").length,noshow:items.filter(a=>a.status==="noshow").length,cancelled:items.filter(a=>a.status==="cancelled").length,waits,buckets,waitAvg:waits.length?waits.reduce((s,x)=>s+x,0)/waits.length:null,waitN:waits.length,delays:Object.entries(delays).map(([pr,l])=>({pr,avg:l.reduce((s,x)=>s+x,0)/l.length,n:l.length})).sort((a,b)=>b.avg-a.avg),byPr,rooms,tasks:{n:tasks.length,done:tasks.filter(t=>t.status==="done").length,overdue:S.tasks.filter(cbOverdue).length},hours}}

