function cbSvcSave(d: Partial<Omit<RmSvc, "dur" | "minDur" | "maxDur" | "id">> & Partial<Record<"fr" | "en" | "de" | "ar" | "dur" | "minDur" | "maxDur" | "b0" | "b1", string>> & { id?: string | null; force?: boolean }){cbNeed("svc.manage");const S=rmShSt();const n=[d.fr,d.en,d.de,d.ar].map(x=>String(x||"").trim().replace(/\|/g,"/"));if(!n[0])throw new CbErr("cb_eInvalid",L4("intitulé (FR)|name (FR)|Bezeichnung (FR)|الاسم (FR)"));
  const dur=+d.dur!,min=+d.minDur!,max=+d.maxDur!,b0=+d.b0!,b1=+d.b1!;if(!(dur>=5&&dur<=480&&min>=5&&max<=480&&min<=dur&&dur<=max))throw new CbErr("cb_eInvalid",L4("durées (min ≤ standard ≤ max, 5–480)|durations (min ≤ standard ≤ max, 5–480)|Dauern|المدد"));if(!(b0>=0&&b0<=60&&b1>=0&&b1<=60))throw new CbErr("cb_eInvalid",L4("temps tampon (0–60 min)|buffer (0–60 min)|Puffer|الفاصل"));
  const rooms=(d.rooms||[]).filter(k=>CL_RTYPES[k]&&k!=="equip");if(!d.tele&&!rooms.length)throw new CbErr("cb_eInvalid",L4("au moins un type de salle (ou téléconsultation)|at least one room type (or telehealth)|mind. ein Raumtyp|نوع غرفة واحد على الأقل"));
  const pracs=(d.pracs||[]).filter(p=>rmPrac(p));if(!pracs.length)throw new CbErr("cb_eInvalid",L4("au moins un·e praticien·ne|at least one practitioner|mind. ein Behandler|ممارس واحد على الأقل"));
  if(d.billSvc&&typeof biSt==="function"&&!biSt().services.some(s=>s.id===d.billSvc))throw new CbErr("cb_eInvalid",L4("référence Facturation|billing reference|Abrechnungsreferenz|مرجع الفوترة"));
  let s=(d.id&&S.services.find(x=>x.id===d.id)) as RmSvc | undefined;const isNew=!s;if(!s){s=<RmSvc><unknown>{id:"sv"+(S.services.length+1)+Math.random().toString(36).slice(2,4),equip:[],intake:null,instr:""};S.services.push(s)}
  Object.assign(s,{n:n.map((x,i)=>x||n[0]).join("|"),spec:RM_SPECS[d.spec!]?d.spec:"other",dur,minDur:min,maxDur:max,buf:[b0,b1],rooms,pracs,billSvc:d.billSvc||null,public:!!d.public,tele:!!d.tele,active:!!d.active,prep:String(d.prep||"").slice(0,300)});
  rmShSave();cbLog(isNew?"svc.create":"svc.edit",s.id,n[0]);rmEmit("service.updated",{svc:s.id,active:s.active},{src:"cabinet",ref:s.id});cbSave();return s}
const cbSvcUse=(id: string)=>{try{return clItems(cbNow(),cbNow()+180*864e5,{active:true}).filter(a=>a.svc===id).length}catch(e){return 0}};
