function cbCsv(){cbNeed("export");const f=CB.ui.tf;const days=+(f.rdays||7);const r=cbReport(days,{est:CB.ui.est,pr:f.rpr||""});const q=(x: unknown)=>{const s=String(x??"");return /[",;\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s};const L: string[]=[];const row=(a: unknown[])=>L.push(a.map(q).join(";"));
  row(["# Remotion OS — Gestion Cabinet — données de démonstration (synthetic)"]);row(["periode",r.from,r.to]);row(["indicateur","valeur","n"]);row(["taux_presence",r.checkinRate.toFixed(3),r.planned]);row(["attente_moyenne_min",r.waitAvg==null?"":r.waitAvg.toFixed(1),r.waitN]);row(["absences",r.noshow,r.n]);row(["termines",r.completed,r.n]);row(["annules",r.cancelled,r.n]);
  row([]);row(["attente_min_de","attente_min_a","visites"]);r.buckets.forEach(b=>row([b.a,b.b===Infinity?"":b.b,b.n]));row([]);row(["praticien","retard_moyen_min","n"]);r.delays.forEach(d=>row([rmPracName(d.pr),d.avg.toFixed(1),d.n]));
  row([]);row(["salle","minutes_ouverture","minutes_reservees","minutes_indisponibles","occupation"]);r.rooms.forEach(x=>row([x.r.n,Math.round(x.open),Math.round(x.booked),Math.round(x.down),x.util.toFixed(3)]));
  cbLog("report.export","",days+" j");cbSave();cbDownload("cabinet-rapport-"+r.from+"-"+r.to+".csv",new Blob(["\ufeff"+L.join("\n")],{type:"text/csv;charset=utf-8"}))}

