function cbPolSave(d: Bag){cbNeed("config");const P=cbSt().pol;const lm=d.lateMins!=null?+d.lateMins:P.lateMins,ng=d.noShowGrace!=null?+d.noShowGrace:P.noShowGrace;if(!(lm>=0&&lm<=120))throw new CbErr("cb_eInvalid",L4("seuil de retard (0–120)|late threshold (0–120)|Verspätung (0–120)|حد التأخير"));if(!(ng>=0&&ng<=240))throw new CbErr("cb_eInvalid",L4("délai d’absence (0–240)|no-show grace (0–240)|Karenz (0–240)|مهلة الغياب"));
  Object.assign(P,{lateMins:lm,noShowGrace:ng},d.walkin!=null?{walkin:!!d.walkin}:{});cbLog("config.policy","",JSON.stringify(P));cbSave()}
function cbHoursSave(est: string,a: string,b: string){cbNeed("config");if(!/^\d\d:\d\d$/.test(a)||!/^\d\d:\d\d$/.test(b)||a>=b)throw new CbErr("cb_eInvalid",L4("horaires d’ouverture|opening hours|Öffnungszeiten|ساعات العمل"));cbSt().hours[est]=[a,b];cbLog("config.hours",est,a+"–"+b);cbSave()}
function cbDispSave(d: { mode?: string; [k: string]: unknown }){cbNeed("config");const D=cbSt().display;if(d.mode&&!["initials","ticket","none"].includes(d.mode))throw new CbErr("cb_eInvalid");Object.assign(D,d);cbLog("config.display","",JSON.stringify(D));cbSave()}
function cbAnnAdd(text: string,pub?: boolean){cbNeed("config");const t=String(text||"").trim();if(!t)throw new CbErr("cb_eInvalid",L4("texte|text|Text|النص"));const S=cbSt();const a={id:cbId("an"),at:new Date().toISOString(),by:cbUser(),text:t.slice(0,240),est:CB.ui.est||"",pub:!!pub};S.ann.unshift(a);cbLog("ann.add",a.id,t.slice(0,60));rmNotify("rmCab",L4("Annonce interne|Internal announcement|Interne Mitteilung|إعلان داخلي"),a.text,{pri:"low"});cbSave();return a}
function cbAnnDel(id: string){cbNeed("config");const S=cbSt();S.ann=S.ann.filter(a=>a.id!==id);cbLog("ann.del",id,"");cbSave()}
