  const log=S.audit.filter(a=>!q||(a.act+" "+a.user+" "+a.detail+" "+a.ref).toLowerCase().includes(q)).slice(0,200);const bus=rmBusSt();const mine=["cabinet"];const ev=bus.ev.filter(e=>e.src==="cabinet"||/^(visit|resource|task|service|practitioner)\./.test(e.type)||(bus.done.cabinet||[]).includes(e.key)).slice(-150).reverse();
