/* ---------- live updates: timers every 15 s; other tabs/apps via storage events; a page is never re-rendered under an open dialog ---------- */
function cbTick(){const R=cbRoot();if(!R)return;R.querySelectorAll<HTMLInputElement>("[data-cbsince]").forEach(el=>{const s=el.dataset.cbsince;if(!s)return;const m=cbMins(cbNow()-Date.parse(s));const n=el.querySelector<HTMLInputElement>("span");if(n&&n.textContent!==String(m))n.textContent=(m) as unknown as string;const tag=el.closest<HTMLInputElement>(".pa-tag");if(tag){tag.classList.toggle("bad",m>=30);tag.classList.toggle("warn",m>=15&&m<30);tag.classList.toggle("info",m<15)}});const b=R.querySelector<HTMLInputElement>(".cb-live");if(b&&!CB.stale)b.lastChild!.textContent=" · "+cbT(CB.syncAt||cbNow())}
function cbExternalChange(){if(!OSW.cabinet)return;cbReload();clReload();const R=cbRoot();if(!R)return;if(R.querySelector<HTMLInputElement>(".hr-dlg")||R.querySelector<HTMLInputElement>(".cb-disp")||R.contains(document.activeElement)&&document.activeElement!.matches("input,textarea,select")){CB.stale=true;const b=R.querySelector<HTMLInputElement>(".cb-live");if(b){b.classList.add("bad");b.title=L4("Des changements ont été faits ailleurs ; l’écran sera actualisé à la fermeture de la fenêtre de dialogue.|Changes were made elsewhere; the screen will refresh when the dialog closes.|Änderungen anderswo.|تغييرات في مكان آخر.")}return}CB.stale=false;CB.syncAt=Date.now();cbRefresh()}
